1	syntax = "proto3";
2	
3	package memos.api.v1;
4	
5	import "api/v1/common.proto";
6	import "google/api/annotations.proto";
7	import "google/api/client.proto";
8	import "google/api/field_behavior.proto";
9	import "google/api/resource.proto";
10	import "google/protobuf/empty.proto";
11	import "google/protobuf/field_mask.proto";
12	import "google/protobuf/timestamp.proto";
13	import "google/type/color.proto";
14	
15	option go_package = "gen/api/v1";
16	
17	service UserService {
18	  // ListUsers returns a list of users.
19	  rpc ListUsers(ListUsersRequest) returns (ListUsersResponse) {
20	    option (google.api.http) = {get: "/api/v1/users"};
21	  }
22	
23	  // BatchGetUsers returns active users by usernames.
24	  rpc BatchGetUsers(BatchGetUsersRequest) returns (BatchGetUsersResponse) {
25	    option (google.api.http) = {
26	      post: "/api/v1/users:batchGet"
27	      body: "*"
28	    };
29	  }
30	
31	  // GetUser gets a user by username.
32	  // Format: users/{username} (e.g., users/steven)
33	  rpc GetUser(GetUserRequest) returns (User) {
34	    option (google.api.http) = {get: "/api/v1/{name=users/*}"};
35	    option (google.api.method_signature) = "name";
36	  }
37	
38	  // CreateUser creates a new user.
39	  rpc CreateUser(CreateUserRequest) returns (User) {
40	    option (google.api.http) = {
41	      post: "/api/v1/users"
42	      body: "user"
43	    };
44	    option (google.api.method_signature) = "user";
45	  }
46	
47	  // UpdateUser updates a user.
48	  rpc UpdateUser(UpdateUserRequest) returns (User) {
49	    option (google.api.http) = {
50	      patch: "/api/v1/{user.name=users/*}"
51	      body: "user"
52	    };
53	    option (google.api.method_signature) = "user,update_mask";
54	  }
55	
56	  // DeleteUser deletes a user.
57	  rpc DeleteUser(DeleteUserRequest) returns (google.protobuf.Empty) {
58	    option (google.api.http) = {delete: "/api/v1/{name=users/*}"};
59	    option (google.api.method_signature) = "name";
60	  }
61	
62	  // ListAllUserStats returns statistics for all users.
63	  rpc ListAllUserStats(ListAllUserStatsRequest) returns (ListAllUserStatsResponse) {
64	    option (google.api.http) = {get: "/api/v1/users:stats"};
65	  }
66	
67	  // GetUserStats returns statistics for a specific user.
68	  rpc GetUserStats(GetUserStatsRequest) returns (UserStats) {
69	    option (google.api.http) = {get: "/api/v1/{name=users/*}:getStats"};
70	    option (google.api.method_signature) = "name";
71	  }
72	
73	  // GetUserSetting returns the user setting.
74	  rpc GetUserSetting(GetUserSettingRequest) returns (UserSetting) {
75	    option (google.api.http) = {get: "/api/v1/{name=users/*/settings/*}"};
76	    option (google.api.method_signature) = "name";
77	  }
78	
79	  // UpdateUserSetting updates the user setting.
80	  rpc UpdateUserSetting(UpdateUserSettingRequest) returns (UserSetting) {

80	  }
81	  // CreateMemoComment creates a comment for a memo.
82	  rpc CreateMemoComment(CreateMemoCommentRequest) returns (Memo) {
83	    option (google.api.http) = {
84	      post: "/api/v1/{name=memos/*}/comments"
85	      body: "comment"
86	    };
87	    option (google.api.method_signature) = "name,comment";
88	  }
89	  // ListMemoComments lists comments for a memo.
90	  rpc ListMemoComments(ListMemoCommentsRequest) returns (ListMemoCommentsResponse) {
91	    option (google.api.http) = {get: "/api/v1/{name=memos/*}/comments"};
92	    option (google.api.method_signature) = "name";
93	  }
94	  // ListMemoReactions lists reactions for a memo.
95	  rpc ListMemoReactions(ListMemoReactionsRequest) returns (ListMemoReactionsResponse) {
96	    option (google.api.http) = {get: "/api/v1/{name=memos/*}/reactions"};
97	    option (google.api.method_signature) = "name";
98	  }
99	  // UpsertMemoReaction adds or updates the authenticated user's reaction on a
100	  // memo. The reaction's content_id is the memo's resource name (memos/{memo}).
101	  rpc UpsertMemoReaction(UpsertMemoReactionRequest) returns (Reaction) {
102	    option (google.api.http) = {
103	      post: "/api/v1/{name=memos/*}/reactions"
104	      body: "*"
105	    };
106	    option (google.api.method_signature) = "name";
107	  }
108	  // DeleteMemoReaction deletes a reaction for a memo.
109	  rpc DeleteMemoReaction(DeleteMemoReactionRequest) returns (google.protobuf.Empty) {
110	    option (google.api.http) = {delete: "/api/v1/{name=memos/*/reactions/*}"};
111	    option (google.api.method_signature) = "name";
112	  }
113	  // CreateMemoShare creates a share link for a memo. Requires authentication as the memo creator.
114	  rpc CreateMemoShare(CreateMemoShareRequest) returns (MemoShare) {
115	    option (google.api.http) = {
116	      post: "/api/v1/{parent=memos/*}/shares"
117	      body: "memo_share"
118	    };
119	    option (google.api.method_signature) = "parent,memo_share";
120	  }
121	  // ListMemoShares lists all share links for a memo. Requires authentication as the memo creator.
122	  rpc ListMemoShares(ListMemoSharesRequest) returns (ListMemoSharesResponse) {
123	    option (google.api.http) = {get: "/api/v1/{parent=memos/*}/shares"};
124	    option (google.api.method_signature) = "parent";
125	  }
126	  // DeleteMemoShare revokes a share link. Requires authentication as the memo creator.
127	  rpc DeleteMemoShare(DeleteMemoShareRequest) returns (google.protobuf.Empty) {
128	    option (google.api.http) = {delete: "/api/v1/{name=memos/*/shares/*}"};
129	    option (google.api.method_signature) = "name";
130	  }
131	  // GetMemoByShare resolves a share token to its memo. No authentication required.
132	  // Returns NOT_FOUND if the token is invalid or expired.
133	  rpc GetMemoByShare(GetMemoByShareRequest) returns (Memo) {
134	    option (google.api.http) = {get: "/api/v1/shares/{share_id}"};
135	  }
136	  // GetLinkMetadata gets metadata for a link.
137	  rpc GetLinkMetadata(GetLinkMetadataRequest) returns (LinkMetadata) {
138	    option (google.api.http) = {get: "/api/v1/memos/-/linkMetadata"};
139	  }
140	  // BatchGetLinkMetadata gets metadata for links.
141	  rpc BatchGetLinkMetadata(BatchGetLinkMetadataRequest) returns (BatchGetLinkMetadataResponse) {
142	    option (google.api.http) = {
143	      post: "/api/v1/memos/-/linkMetadata:batchGet"
144	      body: "*"
145	    };
146	  }
147	}
148	
149	// Visibility controls who can read a memo.
150	enum Visibility {
151	  VISIBILITY_UNSPECIFIED = 0;
152	  // PRIVATE: only the creator can read the memo.
153	  PRIVATE = 1;
154	  // PROTECTED: signed-in users of the instance can read the memo.
155	  PROTECTED = 2;
156	  // PUBLIC: anyone, including anonymous visitors, can read the memo.
157	  PUBLIC = 3;
158	}
159	
160	message Reaction {
161	  option (google.api.resource) = {
162	    type: "memos.api.v1/Reaction"
163	    pattern: "memos/{memo}/reactions/{reaction}"
164	    name_field: "name"
165	    singular: "reaction"
166	    plural: "reactions"
167	  };
168	
169	  // The resource name of the reaction.
170	  // Format: memos/{memo}/reactions/{reaction}
171	  string name = 1 [
172	    (google.api.field_behavior) = OUTPUT_ONLY,
173	    (google.api.field_behavior) = IDENTIFIER
174	  ];
175	
176	  // The resource name of the creator.
177	  // Format: users/{user}
178	  string creator = 2 [
179	    (google.api.field_behavior) = OUTPUT_ONLY,
180	    (google.api.resource_reference) = {type: "memos.api.v1/User"}
181	  ];
182	
183	  // The resource name of the content.
184	  // For memo reactions, this should be the memo's resource name.
185	  // Format: memos/{memo}
186	  string content_id = 3 [
187	    (google.api.field_behavior) = REQUIRED,
188	    (google.api.resource_reference) = {type: "memos.api.v1/Memo"}
189	  ];
190	
191	  // Required. The type of reaction (e.g., "👍", "❤️", "😄").
192	  string reaction_type = 4 [(google.api.field_behavior) = REQUIRED];
193	
194	  // Output only. The creation timestamp.
195	  google.protobuf.Timestamp create_time = 5 [(google.api.field_behavior) = OUTPUT_ONLY];
196	}
197	
198	message Memo {
199	  option (google.api.resource) = {
200	    type: "memos.api.v1/Memo"
201	    pattern: "memos/{memo}"
202	    name_field: "name"
203	    singular: "memo"
204	    plural: "memos"
205	  };
206	
207	  // The resource name of the memo.
208	  // Format: memos/{memo}, memo is the user defined id or uuid.
209	  string name = 1 [(google.api.field_behavior) = IDENTIFIER];
210	
211	  // The state of the memo.
212	  State state = 2 [(google.api.field_behavior) = REQUIRED];
213	
214	  // The name of the creator.
215	  // Format: users/{user}
216	  string creator = 3 [
217	    (google.api.field_behavior) = OUTPUT_ONLY,
218	    (google.api.resource_reference) = {type: "memos.api.v1/User"}
219	  ];
220	
221	  // The creation timestamp.
222	  // If not set on creation, the server will set it to the current time.
223	  google.protobuf.Timestamp create_time = 4 [(google.api.field_behavior) = OPTIONAL];
224	
225	  // The last update timestamp.
226	  // If not set on creation, the server will set it to the current time.
227	  google.protobuf.Timestamp update_time = 5 [(google.api.field_behavior) = OPTIONAL];
228	
229	  reserved 6;
230	  reserved "display_time";
231	
232	  // Required. The content of the memo in Markdown format.
233	  string content = 7 [(google.api.field_behavior) = REQUIRED];
234	
235	  // The visibility of the memo.
236	  // One of PRIVATE (creator only), PROTECTED (signed-in users), or
237	  // PUBLIC (anyone). Defaults to PRIVATE on creation when unspecified.
238	  Visibility visibility = 9 [(google.api.field_behavior) = REQUIRED];
239	
240	  // Output only. The tags extracted from the content.
241	  repeated string tags = 10 [(google.api.field_behavior) = OUTPUT_ONLY];
242	
243	  // Whether the memo is pinned.
244	  bool pinned = 11 [(google.api.field_behavior) = OPTIONAL];
245	
246	  // Optional. The attachments of the memo.
247	  repeated Attachment attachments = 12 [(google.api.field_behavior) = OPTIONAL];
248	
249	  // Optional. The relations of the memo.
250	  repeated MemoRelation relations = 13 [(google.api.field_behavior) = OPTIONAL];
251	
252	  // Output only. The reactions to the memo.
253	  repeated Reaction reactions = 14 [(google.api.field_behavior) = OUTPUT_ONLY];
254	
255	  // Output only. The computed properties of the memo.
256	  Property property = 15 [(google.api.field_behavior) = OUTPUT_ONLY];
257	
258	  // Output only. The name of the parent memo.
259	  // Format: memos/{memo}
260	  optional string parent = 16 [
261	    (google.api.field_behavior) = OUTPUT_ONLY,
262	    (google.api.resource_reference) = {type: "memos.api.v1/Memo"}
263	  ];
264	
265	  // Output only. The snippet of the memo content. Plain text only.
266	  string snippet = 17 [(google.api.field_behavior) = OUTPUT_ONLY];
267	
268	  // Optional. The location of the memo.
269	  optional Location location = 18 [(google.api.field_behavior) = OPTIONAL];
270	
271	  // Computed properties of a memo.
272	  message Property {
273	    bool has_link = 1;
274	    bool has_task_list = 2;
275	    bool has_code = 3;
276	    bool has_incomplete_tasks = 4;
277	    // The title extracted from the first H1 heading, if present.
278	    string title = 5;
279	  }
280	}
281	
282	message Location {
283	  // A placeholder text for the location.
284	  string placeholder = 1 [(google.api.field_behavior) = OPTIONAL];
285	
286	  // The latitude of the location.
287	  double latitude = 2 [(google.api.field_behavior) = OPTIONAL];
288	
289	  // The longitude of the location.
290	  double longitude = 3 [(google.api.field_behavior) = OPTIONAL];
291	}
292	
293	message CreateMemoRequest {
294	  // Required. The memo to create.
295	  Memo memo = 1 [(google.api.field_behavior) = REQUIRED];
296	
297	  // Optional. The memo ID to use for this memo.
298	  // If empty, a unique ID will be generated.
299	  string memo_id = 2 [(google.api.field_behavior) = OPTIONAL];
300	}
301	
302	message ListMemosRequest {
303	  // Optional. The maximum number of memos to return.
304	  // The service may return fewer than this value.
305	  // If unspecified, at most 50 memos will be returned.
306	  // The maximum value is 1000; values above 1000 will be coerced to 1000.
307	  int32 page_size = 1 [(google.api.field_behavior) = OPTIONAL];
308	
309	  // Optional. A page token, received from a previous `ListMemos` call.
310	  // Provide this to retrieve the subsequent page.
311	  string page_token = 2 [(google.api.field_behavior) = OPTIONAL];
312	
313	  // Optional. The state of the memos to list.
314	  // Default to `NORMAL`. Set to `ARCHIVED` to list archived memos.
315	  State state = 3 [(google.api.field_behavior) = OPTIONAL];
316	
317	  // Optional. The order to sort results by.
318	  // Default to "create_time desc".
319	  // Supports comma-separated list of fields following AIP-132.
320	  // Example: "pinned desc, create_time desc" or "update_time asc"
321	  // Supported fields: pinned, create_time, update_time, name.
322	  // Note: order_by uses create_time / update_time, while the filter
323	  // expression uses created_ts / updated_ts for the same timestamps.
324	  string order_by = 4 [(google.api.field_behavior) = OPTIONAL];
325	
326	  // Optional. A CEL expression to filter memos. Combine terms with && and ||.
327	  // Available fields:
328	  //   content (string), creator (string, e.g. "users/1"),
329	  //   created_ts / updated_ts (timestamp), pinned (bool),
330	  //   visibility (string: PRIVATE | PROTECTED | PUBLIC),
331	  //   tags (list<string>; match with `"work" in tags`, not `tag == "work"`),
332	  //   has_task_list / has_link / has_code / has_incomplete_tasks (bool).
333	  // Note: the time fields here are created_ts / updated_ts, which differ from
334	  // the create_time / update_time names used by order_by.
335	  // Examples:
336	  //   pinned == true && visibility == "PUBLIC"
337	  //   tags.exists(t, t == "urgent")
338	  //   content.contains("roadmap") && created_ts > now - duration("168h")
339	  string filter = 5 [(google.api.field_behavior) = OPTIONAL];
340	
341	  // Optional. If true, show deleted memos in the response.
342	  bool show_deleted = 6 [(google.api.field_behavior) = OPTIONAL];
343	}
344	
345	message ListMemosResponse {
346	  // The list of memos.
347	  repeated Memo memos = 1;
348	
349	  // A token that can be sent as `page_token` to retrieve the next page.
350	  // If this field is omitted, there are no subsequent pages.
351	  string next_page_token = 2;
352	}
353	
354	message GetMemoRequest {
355	  // Required. The resource name of the memo.
356	  // Format: memos/{memo}
357	  string name = 1 [
358	    (google.api.field_behavior) = REQUIRED,
359	    (google.api.resource_reference) = {type: "memos.api.v1/Memo"}
360	  ];
361	}
362	
363	message UpdateMemoRequest {
364	  // Required. The memo to update.
365	  // The `name` field is required.
366	  Memo memo = 1 [(google.api.field_behavior) = REQUIRED];
367	
368	  // Required. The list of fields to update.
369	  google.protobuf.FieldMask update_mask = 2 [(google.api.field_behavior) = REQUIRED];
370	}
371	
372	message DeleteMemoRequest {
