247	  // AI provider configuration settings.
248	  message AISetting {
249	    // providers is the list of AI provider configurations available instance-wide.
250	    repeated AIProviderConfig providers = 1;
251	
252	    // transcription is the speech-to-text feature configuration.
253	    // When unset or transcription.provider_id is empty, transcription is disabled.
254	    TranscriptionConfig transcription = 2;
255	  }
256	
257	  // AIProviderConfig represents one callable AI provider connection.
258	  message AIProviderConfig {
259	    string id = 1;
260	    string title = 2;
261	    AIProviderType type = 3;
262	    string endpoint = 4;
263	    // api_key is write-only and is never returned by GetInstanceSetting.
264	    string api_key = 5 [(google.api.field_behavior) = INPUT_ONLY];
265	    // api_key_set indicates whether an API key is stored for this provider.
266	    bool api_key_set = 8 [(google.api.field_behavior) = OUTPUT_ONLY];
267	    // api_key_hint is a masked hint for the stored API key.
268	    string api_key_hint = 9 [(google.api.field_behavior) = OUTPUT_ONLY];
269	  }
270	
271	  // AIProviderType is the provider implementation type.
272	  enum AIProviderType {
273	    AI_PROVIDER_TYPE_UNSPECIFIED = 0;
274	    OPENAI = 1;
275	    GEMINI = 2;
276	  }
277	
278	  // TranscriptionConfig configures the speech-to-text feature.
279	  message TranscriptionConfig {
280	    // provider_id references an entry in AISetting.providers[].id.
281	    // Empty string means transcription is disabled.
282	    string provider_id = 1;
283	
284	    // model is the provider-specific model identifier.
285	    // Empty string falls back to the engine default
286	    // (whisper-1 for OPENAI providers, gemini-2.5-flash for GEMINI providers).
287	    string model = 2;
