1	package mcp
2	
3	import (
4		"regexp"
5		"strings"
6	
7		sdkmcp "github.com/modelcontextprotocol/go-sdk/mcp"
8		"github.com/pkg/errors"
9	)
10	
11	var curatedOperationIDs = []string{
12		"MemoService_ListMemos",
13		"MemoService_CreateMemo",
14		"MemoService_GetMemo",
15		"MemoService_UpdateMemo",
16		"MemoService_DeleteMemo",
17		"MemoService_ListMemoComments",
18		"MemoService_CreateMemoComment",
19		"MemoService_ListMemoAttachments",
20		"MemoService_SetMemoAttachments",
21		"MemoService_ListMemoReactions",
22		"MemoService_UpsertMemoReaction",
23		"MemoService_DeleteMemoReaction",
24		"MemoService_ListMemoRelations",
25		"MemoService_SetMemoRelations",
26		"AttachmentService_ListAttachments",
27		"AttachmentService_CreateAttachment",
28		"AttachmentService_GetAttachment",
29		"AttachmentService_DeleteAttachment",
30		"ShortcutService_ListShortcuts",
31		// The only allowed auth/identity operation: a read-only "whoami" so agents
32		// can resolve the current user (e.g. for ShortcutService_ListShortcuts).
33		"AuthService_GetCurrentUser",
34	}
35	
36	type registeredOperation struct {
37		ToolName    string
38		OperationID string
39		Method      string
40		Path        string
41		Operation   *openAPIOperation
42		InputSchema jsonSchema
43	}
44	
45	var wordBoundary = regexp.MustCompile(`([a-z0-9])([A-Z])`)
46	
47	func buildCuratedTools(registry map[string]*openAPIOperation) ([]*sdkmcp.Tool, map[string]*registeredOperation, error) {
48		tools := make([]*sdkmcp.Tool, 0, len(curatedOperationIDs))
49		operations := map[string]*registeredOperation{}
50		for _, operationID := range curatedOperationIDs {
51			operation, ok := registry[operationID]
52			if !ok {
53				return nil, nil, errors.Errorf("curated OpenAPI operation %q not found", operationID)
54			}
55	
56			tool, registered := buildToolFromOperation(operation)
57			if _, exists := operations[tool.Name]; exists {
58				return nil, nil, errors.Errorf("duplicate MCP tool name %q", tool.Name)
59			}
60	
61			tools = append(tools, tool)
62			operations[tool.Name] = registered
63		}
64		return tools, operations, nil
65	}
66	
67	func buildToolFromOperation(operation *openAPIOperation) (*sdkmcp.Tool, *registeredOperation) {
68		name := toolNameFromOperationID(operation.OperationID)
69		title := titleFromToolName(name)
70		inputSchema := inputSchemaForOperation(operation)
71		tool := &sdkmcp.Tool{
72			Meta: sdkmcp.Meta{
73				"operationId": operation.OperationID,
74				"method":      operation.Method,
75				"path":        operation.Path,
76			},
77			Name:         name,
78			Title:        title,
79			Description:  operation.Description,
80			InputSchema:  inputSchema,
81			OutputSchema: outputSchemaForOperation(operation),
82			Annotations:  annotationsForOperation(operation, title),
83		}
84	
85		return tool, &registeredOperation{
86			ToolName:    name,
87			OperationID: operation.OperationID,
88			Method:      operation.Method,
89			Path:        operation.Path,
90			Operation:   operation,
91			InputSchema: inputSchema,
92		}
93	}
94	
95	func toolNameFromOperationID(operationID string) string {
96		service, method, ok := strings.Cut(operationID, "_")
97		if !ok {
98			return camelToSnake(operationID)
99		}
100		service = strings.TrimSuffix(service, "Service")
101		return camelToSnake(service) + "_" + camelToSnake(method)
102	}
103	
104	func camelToSnake(value string) string {
105		return strings.ToLower(wordBoundary.ReplaceAllString(value, `${1}_${2}`))
106	}
107	
108	func titleFromToolName(name string) string {
109		parts := strings.Split(name, "_")
110		for i, part := range parts {
111			if part == "" {
112				continue
113			}
114			parts[i] = strings.ToUpper(part[:1]) + part[1:]
115		}
116		return strings.Join(parts, " ")
117	}
118	
119	func inputSchemaForOperation(operation *openAPIOperation) jsonSchema {
120		properties := map[string]any{}
121		required := []string{}
122		defs := map[string]any{}
123		for _, parameter := range operation.Parameters {
124			schema := cloneSchema(parameter.Schema)
125			if parameter.Description != "" {
126				schema["description"] = parameter.Description
127			}
128			properties[parameter.Name] = schema
129			if parameter.Required {
130				required = append(required, parameter.Name)
131			}
132		}
133	
134		if operation.RequestBody != nil {
135			bodySchema := requestBodySchema(operation)
136			for name, definition := range extractSchemaDefs(bodySchema) {
137				defs[name] = definition
138			}
139			properties["body"] = bodySchema
140			if operation.RequestBody.Required {
141				required = append(required, "body")
142			}
143		}
144	
145		schema := jsonSchema{
146			"type":                 "object",
147			"properties":           properties,
148			"additionalProperties": false,
149		}
150		if len(required) > 0 {
151			schema["required"] = required
152		}
153		if len(defs) > 0 {
154			schema["$defs"] = defs
155		}
156		return schema
157	}
158	
159	func requestBodySchema(operation *openAPIOperation) jsonSchema {
160		if operation.RequestBodySchema == nil {
161			return jsonSchema{"type": "object"}
162		}
163		return cloneSchema(operation.RequestBodySchema)
164	}
165	
166	func outputSchemaForOperation(operation *openAPIOperation) jsonSchema {
167		if operation.ResponseSchema == nil {
168			return okSchema()
169		}
170		return cloneSchema(operation.ResponseSchema)
171	}
172	
173	func cloneSchema(schema jsonSchema) jsonSchema {
174		clone := jsonSchema{}
175		for key, value := range schema {
176			clone[key] = value
177		}
178		return clone
179	}
180	
181	func extractSchemaDefs(schema jsonSchema) map[string]any {
182		defs, ok := schema["$defs"].(map[string]any)
183		if !ok {
184			return nil
185		}
186		delete(schema, "$defs")
187		return defs
188	}
189	
190	// idempotentOperationIDs lists operations whose idempotency the HTTP-method
191	// heuristic gets wrong. The "Set*" operations declaratively replace the full
192	// set on a memo, so repeating an identical call converges to the same state —
193	// idempotent — even though they are served over PATCH (which the heuristic
194	// treats as non-idempotent).
195	var idempotentOperationIDs = map[string]bool{
196		"MemoService_SetMemoAttachments": true,
197		"MemoService_SetMemoRelations":   true,
198	}
199	
200	// annotationsForOperation derives the method-based annotations and then applies
201	// per-operation overrides that the HTTP method alone cannot express.
202	func annotationsForOperation(operation *openAPIOperation, title string) *sdkmcp.ToolAnnotations {
203		annotations := annotationsForMethod(operation.Method, title)
204		if idempotentOperationIDs[operation.OperationID] {
205			annotations.IdempotentHint = true
206		}
207		return annotations
208	}
209	
210	func annotationsForMethod(method string, title string) *sdkmcp.ToolAnnotations {
211		openWorld := false
212		destructive := false
213		switch strings.ToUpper(method) {
214		case "GET":
215			return &sdkmcp.ToolAnnotations{
216				Title:           title,
217				ReadOnlyHint:    true,
218				DestructiveHint: &destructive,
219				IdempotentHint:  true,
220				OpenWorldHint:   &openWorld,
221			}
222		case "DELETE":
223			destructive = true
224			return &sdkmcp.ToolAnnotations{
225				Title:           title,
226				ReadOnlyHint:    false,
227				DestructiveHint: &destructive,
228				IdempotentHint:  true,
229				OpenWorldHint:   &openWorld,
230			}
231		default:
232			return &sdkmcp.ToolAnnotations{
233				Title:           title,
234				ReadOnlyHint:    false,
235				DestructiveHint: &destructive,
236				IdempotentHint:  false,
237				OpenWorldHint:   &openWorld,
238			}
239		}
240	}
