1	package mcp
2	
3	import (
4		"os"
5		"strings"
6	
7		"github.com/pkg/errors"
8		"gopkg.in/yaml.v3"
9	)
10	
11	type jsonSchema map[string]any
12	
13	type openAPISpec struct {
14		OpenAPI    string                                  `yaml:"openapi"`
15		Paths      map[string]map[string]*openAPIOperation `yaml:"paths"`
16		Components openAPIComponents                       `yaml:"components"`
17	}
18	
19	type openAPIComponents struct {
20		Schemas map[string]jsonSchema `yaml:"schemas"`
21	}
22	
23	type openAPIOperation struct {
24		OperationID       string                     `yaml:"operationId"`
25		Description       string                     `yaml:"description"`
26		Parameters        []openAPIParameter         `yaml:"parameters"`
27		RequestBody       *openAPIRequestBody        `yaml:"requestBody"`
28		Responses         map[string]openAPIResponse `yaml:"responses"`
29		Method            string                     `yaml:"-"`
30		Path              string                     `yaml:"-"`
31		ResponseSchema    jsonSchema                 `yaml:"-"`
32		RequestBodySchema jsonSchema                 `yaml:"-"`
33	}
34	
35	type openAPIParameter struct {
36		Name        string     `yaml:"name"`
37		In          string     `yaml:"in"`
38		Description string     `yaml:"description"`
39		Required    bool       `yaml:"required"`
40		Schema      jsonSchema `yaml:"schema"`
41	}
42	
43	type openAPIRequestBody struct {
44		Required bool                        `yaml:"required"`
45		Content  map[string]openAPIMediaType `yaml:"content"`
46	}
47	
48	type openAPIResponse struct {
49		Description string                      `yaml:"description"`
50		Content     map[string]openAPIMediaType `yaml:"content"`
51	}
52	
53	type openAPIMediaType struct {
54		Schema jsonSchema `yaml:"schema"`
55	}
56	
57	func loadOpenAPISpec(path string) (*openAPISpec, error) {
58		data, err := os.ReadFile(path)
59		if err != nil {
60			return nil, errors.Wrap(err, "failed to read OpenAPI spec")
61		}
62	
63		spec := &openAPISpec{}
64		if err := yaml.Unmarshal(data, spec); err != nil {
65			return nil, errors.Wrap(err, "failed to parse OpenAPI spec")
66		}
67		if spec.Paths == nil {
68			return nil, errors.New("OpenAPI spec has no paths")
69		}
70		return spec, nil
71	}
72	
73	func buildOperationRegistry(spec *openAPISpec) (map[string]*openAPIOperation, error) {
74		registry := map[string]*openAPIOperation{}
75		for path, pathItem := range spec.Paths {
76			for method, operation := range pathItem {
77				if operation == nil || operation.OperationID == "" {
78					continue
79				}
80				if _, exists := registry[operation.OperationID]; exists {
81					return nil, errors.Errorf("duplicate OpenAPI operationId %q", operation.OperationID)
82				}
83	
84				operation.Method = strings.ToUpper(method)
85				operation.Path = path
86	
87				responseSchema, err := operationSuccessResponseSchema(spec, operation)
88				if err != nil {
89					return nil, errors.Wrapf(err, "failed to resolve response schema for %s", operation.OperationID)
90				}
91				operation.ResponseSchema = responseSchema
92	
93				requestBodySchema, err := operationRequestBodySchema(spec, operation)
94				if err != nil {
95					return nil, errors.Wrapf(err, "failed to resolve request body schema for %s", operation.OperationID)
96				}
97				operation.RequestBodySchema = requestBodySchema
98	
99				registry[operation.OperationID] = operation
100			}
101		}
102		return registry, nil
103	}
104	
105	func operationSuccessResponseSchema(spec *openAPISpec, operation *openAPIOperation) (jsonSchema, error) {
106		response, ok := operation.Responses["200"]
107		if !ok || response.Content == nil {
108			return okSchema(), nil
109		}
110		mediaType, ok := response.Content["application/json"]
111		if !ok || mediaType.Schema == nil {
112			return okSchema(), nil
113		}
114		return resolveSchemaRef(spec, mediaType.Schema)
115	}
116	
117	func operationRequestBodySchema(spec *openAPISpec, operation *openAPIOperation) (jsonSchema, error) {
118		if operation.RequestBody == nil {
119			return nil, nil
120		}
121		mediaType, ok := operation.RequestBody.Content["application/json"]
122		if !ok || mediaType.Schema == nil {
123			return jsonSchema{"type": "object"}, nil
124		}
125		return resolveSchemaRef(spec, mediaType.Schema)
126	}
127	
128	func resolveSchemaRef(spec *openAPISpec, schema jsonSchema) (jsonSchema, error) {
129		defs := map[string]any{}
130		resolved, err := resolveSchemaValue(spec, schema, defs, map[string]bool{}, true)
131		if err != nil {
132			return nil, err
133		}
134	
135		resolvedSchema, ok := resolved.(map[string]any)
136		if !ok {
137			return nil, errors.New("resolved schema is not an object")
138		}
139		if len(defs) > 0 {
140			resolvedSchema["$defs"] = defs
141		}
142		return jsonSchema(resolvedSchema), nil
143	}
144	
145	func resolveSchemaValue(spec *openAPISpec, value any, defs map[string]any, resolving map[string]bool, inlineRef bool) (any, error) {
146		switch typed := value.(type) {
147		case jsonSchema:
148			return resolveSchemaMap(spec, map[string]any(typed), defs, resolving, inlineRef)
149		case map[string]any:
150			return resolveSchemaMap(spec, typed, defs, resolving, inlineRef)
151		case []any:
152			resolved := make([]any, 0, len(typed))
153			for _, item := range typed {
154				resolvedItem, err := resolveSchemaValue(spec, item, defs, resolving, false)
155				if err != nil {
156					return nil, err
157				}
158				resolved = append(resolved, resolvedItem)
159			}
160			return resolved, nil
161		default:
162			return value, nil
163		}
164	}
165	
166	func resolveSchemaMap(spec *openAPISpec, schema map[string]any, defs map[string]any, resolving map[string]bool, inlineRef bool) (map[string]any, error) {
167		if ref, ok := schema["$ref"].(string); ok && ref != "" {
168			name, err := schemaComponentName(ref)
169			if err != nil {
170				return nil, err
171			}
172			if inlineRef {
173				return resolveComponentSchema(spec, name, defs, resolving)
174			}
175			if err := addSchemaDef(spec, name, defs, resolving); err != nil {
176				return nil, err
177			}
178			return map[string]any{"$ref": "#/$defs/" + name}, nil
179		}
180	
181		resolved := make(map[string]any, len(schema))
182		for key, value := range schema {
183			resolvedValue, err := resolveSchemaValue(spec, value, defs, resolving, false)
184			if err != nil {
185				return nil, err
186			}
187			resolved[key] = resolvedValue
188		}
189		return resolved, nil
190	}
191	
192	func resolveComponentSchema(spec *openAPISpec, name string, defs map[string]any, resolving map[string]bool) (map[string]any, error) {
193		component, ok := spec.Components.Schemas[name]
194		if !ok {
195			return nil, errors.Errorf("schema ref %q not found", schemaComponentRef(name))
196		}
197		resolving[name] = true
198		resolved, err := resolveSchemaMap(spec, map[string]any(component), defs, resolving, false)
199		delete(resolving, name)
200		if err != nil {
201			return nil, err
202		}
203		if _, ok := defs[name]; ok {
204			defs[name] = resolved
205		}
206		return resolved, nil
207	}
208	
209	func addSchemaDef(spec *openAPISpec, name string, defs map[string]any, resolving map[string]bool) error {
210		if _, ok := defs[name]; ok {
211			return nil
212		}
213		component, ok := spec.Components.Schemas[name]
214		if !ok {
215			return errors.Errorf("schema ref %q not found", schemaComponentRef(name))
216		}
217	
218		defs[name] = map[string]any{}
219		if resolving[name] {
220			return nil
221		}
222	
223		resolving[name] = true
224		resolved, err := resolveSchemaMap(spec, map[string]any(component), defs, resolving, false)
225		delete(resolving, name)
226		if err != nil {
227			return err
228		}
229		defs[name] = resolved
230		return nil
231	}
232	
233	func schemaComponentName(ref string) (string, error) {
234		const prefix = "#/components/schemas/"
235		if !strings.HasPrefix(ref, prefix) {
236			return "", errors.Errorf("unsupported schema ref %q", ref)
237		}
238		return strings.TrimPrefix(ref, prefix), nil
239	}
240	
241	func schemaComponentRef(name string) string {
242		return "#/components/schemas/" + name
243	}
244	
245	func okSchema() jsonSchema {
246		return jsonSchema{
247			"type": "object",
248			"properties": map[string]any{
249				"ok": map[string]any{"type": "boolean"},
250			},
251		}
252	}
